struct ListNode *removeDuplicateNodes(struct ListNode *head) {
  int seen[20001] = {0};
  struct ListNode dummy;
  dummy.next = head;
  struct ListNode *prev = &dummy, *cur = head;
  while (cur) {
    int idx = cur->val + 10000;
    if (seen[idx]) {
      prev->next = cur->next;
      free(cur);
      cur = prev->next;
    } else {
      seen[idx] = 1;
      prev = cur;
      cur = cur->next;
    }
  }
  return dummy.next;
}

class Solution {
public:
  ListNode *removeDuplicateNodes(ListNode *head) {
    unordered_set<int> seen;
    ListNode dummy(0);
    dummy.next = head;
    ListNode *prev = &dummy, *cur = head;
    while (cur) {
      if (seen.count(cur->val)) {
        prev->next = cur->next;
        delete cur;
        cur = prev->next;
      } else {
        seen.insert(cur->val);
        prev = cur;
        cur = cur->next;
      }
    }
    return dummy.next;
  }
};

func removeDuplicateNodes(head *ListNode) *ListNode {
	seen := make(map[int]bool)
	dummy := &ListNode{Next: head}
	prev, cur := dummy, head
	for cur != nil {
		if seen[cur.Val] {
			prev.Next = cur.Next
			cur = prev.Next
		} else {
			seen[cur.Val] = true
			prev = cur
			cur = cur.Next
		}
	}
	return dummy.Next
}

class ListNode {
  int val;
  ListNode next;

  ListNode(int x) {
    val = x;
  }
}

class Solution {
  public ListNode removeDuplicateNodes(ListNode head) {
    Set<Integer> seen = new HashSet<>();
    ListNode dummy = new ListNode(0);
    dummy.next = head;
    ListNode prev = dummy, cur = head;
    while (cur != null) {
      if (seen.contains(cur.val)) {
        prev.next = cur.next;
        cur = prev.next;
      } else {
        seen.add(cur.val);
        prev = cur;
        cur = cur.next;
      }
    }
    return dummy.next;
  }
}

class Solution:
    def removeDuplicateNodes(self, head: ListNode) -> ListNode:
        seen = set()
        dummy = ListNode(0)
        dummy.next = head
        prev, cur = dummy, head
        while cur:
            if cur.val in seen:
                prev.next = cur.next
                cur = prev.next
            else:
                seen.add(cur.val)
                prev = cur
                cur = cur.next
        return dummy.next

impl Solution {
  pub fn remove_duplicate_nodes(head: Option<Box<ListNode>>) -> Option<Box<ListNode>> {
    let mut seen = HashSet::new();
    let mut vals = vec![];
    let mut cur = head;
    while let Some(node) = cur {
      if seen.insert(node.val) {
        vals.push(node.val);
      }
      cur = node.next;
    }
    let mut dummy = ListNode::new(0);
    let mut tail = &mut dummy;
    for v in vals {
      tail.next = Some(Box::new(ListNode::new(v)));
      tail = tail.next.as_mut().unwrap();
    }
    dummy.next
  }
}

const removeDuplicateNodes = (head: ListNode | null): ListNode | null => {
  const seen = new Set<number>();
  const dummy = new ListNode(0, head);
  let prev: ListNode = dummy;
  let cur = head;
  while (cur) {
    if (seen.has(cur.val)) {
      prev.next = cur.next;
      cur = prev.next;
    } else {
      seen.add(cur.val);
      prev = cur;
      cur = cur.next;
    }
  }
  return dummy.next;
};
